    # AS3 has \b, \f and \v; Haxe has none of them. Each is a control character with an exact hex
    # equivalent, and the M2 lexer patch makes \x lexable, so these preserve the byte precisely.
    # A corpus scan found these three escapes and no others -- everything else that looked
    # unsupported was inside a regex literal, where the backslash is not a string escape at all.
    # Kept as three rules rather than one callable so each carries its own count guard and the
    # manifest can serialise them.
    # A backslash escape only counts when it is not itself escaped. JSONEncoder writes the
    # two-character JSON *output* "\\b" -- a backslash followed by a letter -- which must survive
    # verbatim, so every pattern below refuses to match when preceded by a backslash.
    {
        "id": "escape-backspace",
        "reason": "AS3 \\b has no Haxe spelling; \\x08 is the same character",
        "kind": "regex",
        "pattern": r'(?<!\\)\\b',
        "replacement": r"\\x08",
        "expect": {"adobe/serialization/json": 2},
    },
    {
        "id": "escape-formfeed",
        "reason": "AS3 \\f has no Haxe spelling; \\x0C is the same character",
        "kind": "regex",
        "pattern": r'(?<!\\)\\f',
        "replacement": r"\\x0C",
        "expect": {"adobe/serialization/json": 2},
    },
    {
        "id": "escape-vertical-tab",
        "reason": "AS3 \\v has no Haxe spelling; \\x0B is the same character",
        "kind": "regex",
        "pattern": r'(?<!\\)\\v',
        "replacement": r"\\x0B",
        "expect": {"adobe/serialization/json": 0},
    },
