# Wall tops and floors reach RoomPlane.draw with a sheared, half-scaled matrix that fails its own
# pixel-exact fast path (which admits only a==1, d==1, c==0), so they fall back to
# BitmapData.draw. Flash rasterised that with hard pixel edges; OpenFL applies `smoothing=false`
# to interior sampling only and lets the canvas antialias the transformed quad's boundary, baking
# partial alpha into the plane bitmap. Composited, that is the dark staircase along wall tops.
#
# Measured on a forced rebuild: wall tops arrive as a=1 b=0.5 c=-1 d=0.5 over a 256x8 source,
# wall faces as a=1 b=0.5 c=0 d=1. Only the faces pass the gate, which is exactly why the artifact
# is confined to the sloping tops.
#
# The replacement is a nearest-neighbour inverse-mapped blit injected into RoomPlane itself, so it
# converts through the ordinary pipeline: no ax3 filter, no compat entry, and nothing that touches
# BitmapData.draw for the window toolkit or text. Room geometry and the surrounding plane logic are
# untouched -- only the rasterisation of an already-computed transform changes.
_ROOMPLANE_HARD_EDGE_SITES = {
    "closure:v7_guest_room_closure": 1,
    "closure:v13_visualization_factory_closure": 1,
    "closure:v19_room_engine_closure": 1,
    "closure:v31_full_client_candidate_closure": 1,
    "closure:v32_component_graph_boot_closure": 1,
}

